INSERT INTO `layout_specs` (`id`,`form_code`,`schedule_code`,`variant_key`,`version_label`,`validator_version`,`effective_from`,`effective_to`,`status`,`confidence`,`filename_pattern`,`delimiter`,`line_ending`,`trailing_newline`,`encoding`,`column_header_row`,`text_policy`,`source_ref`,`notes`,`created_by`,`approved_by`,`approved_at`,`approval_evidence_id`,`created_at`,`updated_at`) VALUES
('1','SLS','S1',NULL,'RELIEF SLSP (v2.x observed)','RELIEF','2012-01-01',NULL,'pending_verification','medium','{TIN}S{MM}{YYYY}.DAT',',','CRLF','1','Windows-1252','0','bir_upper','Field order agreed by two independent generators: github.com/cpa-coder/vat-relief (RELIEF v2.3) and github.com/AlmyrCPA/Haki-Bookkeeping-System. Quoting and amount formatting differ between them; this layout follows the RELIEF v2.3 generator. Confirm against the RELIEF validation module before approval.','RELIEF files carry no branch field: one file per TIN per month covering all branches. Detail rows are consolidated per customer TIN.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('2','SLP','S1',NULL,'RELIEF SLSP (v2.x observed)','RELIEF','2012-01-01',NULL,'pending_verification','medium','{TIN}P{MM}{YYYY}.DAT',',','CRLF','1','Windows-1252','0','bir_upper','Same sources as Sales. Creditable input tax = input tax less non-creditable input tax (RELIEF v2.3 generator).','Detail rows are consolidated per supplier TIN.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('3','SLI','S1',NULL,'RELIEF SLSP (single source)','RELIEF','2012-01-01',NULL,'pending_verification','low','{TIN}I{MM}{YYYY}.DAT',',','CRLF','1','Windows-1252','0','bir_upper','Single secondary source (github.com/AlmyrCPA/Haki-Bookkeeping-System). Confirm with the RELIEF module before approval.','One detail row per import entry.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('4','1601EQ','S1',NULL,'Alphalist v7.x QAP','7.4','2018-01-01',NULL,'pending_verification','medium','{TIN}{BRANCH}{MM}{YYYY}1601EQ.DAT',',','CRLF','1','Windows-1252','0','bir_upper','Header shape mirrors the official MAP header (RMC 25-2024 Annex A, reproduced verbatim by Forvis Mazars). Detail/control order from one secondary generator. BIR job aid (RMC 7-2021 Annex C): QAP produces 3 files per quarter, one per month. Filename follows Annex B pattern TIN(9)+BC(4)+MMYYYY+form.','Generate one file per month of the quarter.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('5','1601EQ','S2',NULL,'Analog draft (unsourced)','7.4','2018-01-01',NULL,'draft','analog','{TIN}{BRANCH}{MM}{YYYY}1601EQ.DAT',',','CRLF','1','Windows-1252','0','bir_upper','No published field table was obtainable at build time (RMC 25-2024 / RMC 15-2025 Annex A are image-only PDFs). Mirrors the 1601-EQ layout so the workflow can be exercised. Replace every field from Annex A before approval.','Research pending. Files from this layout are always labelled UNVALIDATED DRAFT.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('6','1601FQ','S1',NULL,'Analog draft (unsourced)','7.4','2018-01-01',NULL,'draft','analog','{TIN}{BRANCH}{MM}{YYYY}1601FQ.DAT',',','CRLF','1','Windows-1252','0','bir_upper','No published field table was obtainable at build time (RMC 25-2024 / RMC 15-2025 Annex A are image-only PDFs). Mirrors the 1601-EQ layout so the workflow can be exercised. Replace every field from Annex A before approval.','Research pending. Files from this layout are always labelled UNVALIDATED DRAFT.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('7','1601FQ','S2',NULL,'Analog draft (unsourced)','7.4','2018-01-01',NULL,'draft','analog','{TIN}{BRANCH}{MM}{YYYY}1601FQ.DAT',',','CRLF','1','Windows-1252','0','bir_upper','No published field table was obtainable at build time (RMC 25-2024 / RMC 15-2025 Annex A are image-only PDFs). Mirrors the 1601-EQ layout so the workflow can be exercised. Replace every field from Annex A before approval.','Research pending. Files from this layout are always labelled UNVALIDATED DRAFT.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('8','1601FQ','S3',NULL,'Analog draft (unsourced)','7.4','2018-01-01',NULL,'draft','analog','{TIN}{BRANCH}{MM}{YYYY}1601FQ.DAT',',','CRLF','1','Windows-1252','0','bir_upper','No published field table was obtainable at build time (RMC 25-2024 / RMC 15-2025 Annex A are image-only PDFs). Mirrors the 1601-EQ layout so the workflow can be exercised. Replace every field from Annex A before approval.','Research pending. Files from this layout are always labelled UNVALIDATED DRAFT.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('9','1600VT','S1',NULL,'Alphalist v7.x MAP','7.4','2018-01-01',NULL,'draft','analog','{TIN}{BRANCH}{MM}{YYYY}1600VT.DAT',',','CRLF','1','Windows-1252','0','bir_upper','Header record and filename: RMC 25-2024 Annex A/B (verbatim reproduction by Forvis Mazars) - official. Detail and control records: not found, mirror the QAP layout (analog).','Header is official; detail and control are drafts. Annex B misprints 1600VT as 1600VY.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('10','1600PT','S1',NULL,'Alphalist v7.x MAP','7.4','2018-01-01',NULL,'draft','analog','{TIN}{BRANCH}{MM}{YYYY}1600PT.DAT',',','CRLF','1','Windows-1252','0','bir_upper','Header record and filename: RMC 25-2024 Annex A/B (verbatim reproduction by Forvis Mazars) - official. Detail and control records: not found, mirror the QAP layout (analog).','Header is official; detail and control are drafts. Annex B misprints 1600VT as 1600VY.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('11','1604C','S1',NULL,'Alphalist v7.4 (TY2025 sample)','7.4','2024-01-01',NULL,'pending_verification','validated','{TIN}{BRANCH}{MMDDYYYY}1604C.DAT',',','CRLF','1','Windows-1252','0','bir_upper','Byte layout reproduced from a v7.4 sample (github.com/ReyJrFerrer/BIR-dat, res/6847855100000123120251604C.DAT) whose BIR validator report reads \"No Errors Encountered\". Code lists from RMC 160-2022 attachment. One sample does not cover previous-employer, refund or PERA cases.','H1604C has 4 fields; each employee is one D1 line of 49 fields; C1 has 36 fields. The test suite reproduces the sample byte for byte.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('12','1604C','S2',NULL,'Analog draft (unsourced)','7.4','2024-01-01',NULL,'draft','analog','{TIN}{BRANCH}{MMDDYYYY}1604C.DAT',',','CRLF','1','Windows-1252','0','bir_upper','Column set follows the printed 1604-C Schedule 2 in the RMC 160-2022 attachment. DAT positions and the D2 record code are not confirmed.','Research pending. Minimum wage earners must not be inferred from income alone.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('13','1604E','S3',NULL,'Analog draft (unsourced)','7.4','2018-01-01',NULL,'draft','analog','{TIN}{BRANCH}{MMDDYYYY}1604E.DAT',',','CRLF','1','Windows-1252','0','bir_upper','Annex A/B of RMC 25-2024 lists these schedules but the PDF is image-only. Header mirrors the validated H1604C shape; detail mirrors QAP. Replace from Annex A before approval.','Research pending. Files are always labelled UNVALIDATED DRAFT.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
('14','1604E','S4',NULL,'Analog draft (unsourced)','7.4','2018-01-01',NULL,'draft','analog','{TIN}{BRANCH}{MMDDYYYY}1604E.DAT',',','CRLF','1','Windows-1252','0','bir_upper','Annex A/B of RMC 25-2024 lists these schedules but the PDF is image-only. Header mirrors the validated H1604C shape; detail mirrors QAP. Replace from Annex A before approval.','Research pending. Files are always labelled UNVALIDATED DRAFT.',NULL,NULL,NULL,NULL,'2026-10-17 07:32:53','2026-10-17 07:32:53'),
